from collections import deque

def components(grid,color):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==color and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));co=[]
    while q:
     x,y=q.pop();co.append((x,y))
     for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
      if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:seen.add((a,b));q.append((a,b))
    comps.append(co)
 return comps

def normshape(coords):
 mr=min(x for x,y in coords);mc=min(y for x,y in coords)
 return frozenset((x-mr,y-mc) for x,y in coords)
def variants(shape,reflections=True):
 curr=set()
 for flip in ([1,-1] if reflections else [1]):
  for k in range(4):
   pts=[]
   for x,y in shape:
    y*=flip
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   curr.add(normshape(pts))
 return curr

def paintmatches(grid,shape,vs):
 h,w=len(grid),len(grid[0]); out=[row[:] for row in grid];matches=[]
 for sh in vs:
  hh=max(x for x,y in sh)+1;ww=max(y for x,y in sh)+1
  for r in range(h-hh+1):
   for c in range(w-ww+1):
    pos=[(r+x,c+y) for x,y in sh]
    if all(grid[x][y]==0 for x,y in pos):
     matches.append(pos)
     for x,y in pos:out[x][y]=4
 return out,matches
