def match_mask(grid,shape,vs,color):
 h,w=len(grid),len(grid[0]); mask=set();matches=[]
 for sh in vs:
  hh=max(x for x,y in sh)+1;ww=max(y for x,y in sh)+1
  for r in range(h-hh+1):
   for c in range(w-ww+1):
    pos=[(r+x,c+y) for x,y in sh]
    if all(grid[x][y]==0 for x,y in pos):
     matches.append(pos);mask.update(pos)
 return mask,matches

